CREATE TABLE IF NOT EXISTS runtime_videos (id text PRIMARY KEY, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_users (id text PRIMARY KEY, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_tags (id text PRIMARY KEY, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_categories (id text PRIMARY KEY, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_favorites (id text PRIMARY KEY, user_id text NOT NULL, video_id text NOT NULL, mode text NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS runtime_favorites_user ON runtime_favorites(user_id,mode);
CREATE TABLE IF NOT EXISTS runtime_progress (id text PRIMARY KEY, user_id text NOT NULL, video_id text NOT NULL, mode text NOT NULL, updated_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS runtime_progress_user ON runtime_progress(user_id,mode,updated_at DESC);
CREATE TABLE IF NOT EXISTS runtime_analytics_events (id text PRIMARY KEY, event_name text NOT NULL, event_time timestamptz NOT NULL, install_id text NOT NULL, channel text NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS runtime_analytics_time_name ON runtime_analytics_events(event_time,event_name);
CREATE INDEX IF NOT EXISTS runtime_analytics_channel_time ON runtime_analytics_events(channel,event_time);
CREATE TABLE IF NOT EXISTS runtime_channels (id text PRIMARY KEY, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_product_lines (id text PRIMARY KEY, slug text NOT NULL UNIQUE, status text NOT NULL, updated_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS runtime_product_status ON runtime_product_lines(status,updated_at DESC);
CREATE TABLE IF NOT EXISTS runtime_collector_sources (id text PRIMARY KEY, source_key text NOT NULL UNIQUE, enabled boolean NOT NULL, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_audit_logs (id text PRIMARY KEY, created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS runtime_audit_created ON runtime_audit_logs(created_at DESC);
CREATE TABLE IF NOT EXISTS runtime_media_jobs (id text PRIMARY KEY, status text NOT NULL, created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS runtime_media_jobs_status ON runtime_media_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS runtime_settings (key text PRIMARY KEY, payload jsonb NOT NULL);
